window.RTLBenchLSData.register("assets/d3f6ab1873676546f91c5c864bcb623607ef9b8b60d73b12277387f3f8ab6c0a.txt","module origen_097092 (\n    input [6:0] opcode,\n    input reset,\n    input invert,\n    input [2:0] funct,\n    output reg [1:0] im_sel,\n    output reg jump,\n    output reg branch,\n    output reg Alusrc1,\n    output reg Alusrc2,\n    output reg regWrite,\n    output reg MemRead,\n    output reg MemWrite,\n    output reg jal,\n    output reg csr,\n    output reg [1:0] wr_sel,\n    output reg [2:0] ALUop,\n    output wire fence\n);\n\n    // FENCE instruction detection (combinatorial)\n    assign fence = (opcode == 7'b0001111);\n\n    // Main control logic\n    always @(*) begin\n        if (reset) begin\n            // Reset all outputs to inactive state\n            im_sel = 2'b00;\n            jump = 1'b0;\n            branch = 1'b0;\n            Alusrc1 = 1'b0;\n            Alusrc2 = 1'b0;\n            regWrite = 1'b0;\n            MemRead = 1'b0;\n            MemWrite = 1'b0;\n            jal = 1'b0;\n            csr = 1'b0;\n            wr_sel = 2'b00;\n            ALUop = 3'b000;\n        end else begin\n            // Default values\n            im_sel = 2'b00;\n            jump = 1'b0;\n            branch = 1'b0;\n            Alusrc1 = 1'b0;\n            Alusrc2 = 1'b0;\n            regWrite = 1'b0;\n            MemRead = 1'b0;\n            MemWrite = 1'b0;\n            jal = 1'b0;\n            csr = 1'b0;\n            wr_sel = 2'b00;\n            ALUop = 3'b000;\n\n            // Decode opcode\n            case (opcode)\n                // R-type: 0110011\n                7'b0110011: begin\n                    regWrite = 1'b1;\n                    Alusrc2 = 1'b0;\n                    im_sel = 2'b00;\n                    ALUop = {1'b0, funct[2:1]};\n                    wr_sel = 2'b00;\n                end\n\n                // I-type: 0010011\n                7'b0010011: begin\n                    regWrite = 1'b1;\n                    Alusrc2 = 1'b1;\n                    im_sel = 2'b00;\n                    ALUop = {1'b0, funct[2:1]};\n                    wr_sel = 2'b00;\n                end\n\n                // S-type: 0100011\n                7'b0100011: begin\n                    Alusrc2 = 1'b1;\n                    MemWrite = 1'b1;\n                    im_sel = 2'b01;\n                    ALUop = 3'b000;\n                end\n\n                // B-type: 1100011\n                7'b1100011: begin\n                    branch = 1'b1;\n                    im_sel = 2'b10;\n                    ALUop = 3'b001;\n                end\n\n                // U-type (LUI): 0110111\n                7'b0110111: begin\n                    regWrite = 1'b1;\n                    Alusrc1 = 1'b1;\n                    Alusrc2 = 1'b1;\n                    im_sel = 2'b11;\n                    ALUop = 3'b000;\n                    wr_sel = 2'b00;\n                end\n\n                // U-type (AUIPC): 0010111\n                7'b0010111: begin\n                    regWrite = 1'b1;\n                    Alusrc1 = 1'b1;\n                    Alusrc2 = 1'b1;\n                    im_sel = 2'b11;\n                    ALUop = 3'b000;\n                    wr_sel = 2'b00;\n                end\n\n                // J-type (JAL): 1101111\n                7'b1101111: begin\n                    regWrite = 1'b1;\n                    jump = 1'b1;\n                    jal = 1'b1;\n                    im_sel = 2'b11;\n                    wr_sel = 2'b10;\n                end\n\n                // Load instructions (I-type with memory): 0000011\n                7'b0000011: begin\n                    regWrite = 1'b1;\n                    Alusrc2 = 1'b1;\n                    MemRead = 1'b1;\n                    im_sel = 2'b00;\n                    ALUop = 3'b000;\n                    wr_sel = 2'b01;\n                end\n\n                // CSR instructions: 1110011\n                7'b1110011: begin\n                    csr = 1'b1;\n                    regWrite = 1'b1;\n                    wr_sel = 2'b01;\n                end\n\n                // Default: maintain all zeros\n                default: begin\n                    im_sel = 2'b00;\n                    jump = 1'b0;\n                    branch = 1'b0;\n                    Alusrc1 = 1'b0;\n                    Alusrc2 = 1'b0;\n                    regWrite = 1'b0;\n                    MemRead = 1'b0;\n                    MemWrite = 1'b0;\n                    jal = 1'b0;\n                    csr = 1'b0;\n                    wr_sel = 2'b00;\n                    ALUop = 3'b000;\n                end\n            endcase\n        end\n    end\n\nendmodule");
